"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  ShoppingBag,
  Bell,
  Heart,
  Share2,
  Star,
  ShieldCheck,
  Truck,
  RotateCcw,
} from "lucide-react";
import Gallery from "./components/gallery";
import VideoShowcase from "./components/video-showcase";
import { Product } from "@/data/store-data";
import Link from "next/link";

export default function ProductPageMaster({
  product,
  similarProducts,
}: {
  product: Product;
  similarProducts: Product[];
}) {
  const [selectedSize, setSelectedSize] = useState<string | null>(null);
  const [isFavorite, setIsFavorite] = useState(false);
  const sizes = ["38", "39", "40", "41", "42", "43", "44", "45"];
  const cols = Math.ceil(sizes.length / 2);
  const [isWishlisted, setIsWishlisted] = useState(true);

  const handleShare = async () => {
    if (navigator.share) {
      try {
        await navigator.share({
          title: product.name,
          text: `Check out the ${product.name} on Fashion Friday!`,
          url: window.location.href,
        });
      } catch (err) {
        console.log("Share failed", err);
      }
    }
  };

  return (
    <div className="bg-background text-foreground min-h-screen pb-32 transition-colors">
      {/* --- MAIN PRODUCT GRID --- */}
      <section className="max-w-7xl mx-auto px-4 md:px-8 pt-6 lg:pt-12">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 items-start">
          {/* LEFT: Gallery */}
          <div className="lg:col-span-7">
            <Gallery
              images={[product.promoImage, ...product.liveImages]}
              videoUrl={product.videoUrl}
            />{" "}
          </div>

          {/* RIGHT: Info & Purchase */}
          <div className="lg:col-span-5 lg:sticky lg:top-24 space-y-8">
            {/* 1. Brand & Actions */}
            <div className="flex justify-between items-start">
              <div>
                <p className="text-[10px] font-black uppercase tracking-[0.3em] text-foreground-muted mb-2">
                  {product.brand} • {product.quality}
                </p>
                <h1 className="text-3xl md:text-5xl uppercase tracking-tighter leading-[0.85]">
                  {product.name}
                </h1>
              </div>
              <div className="flex gap-2">
                <button
                  onClick={handleShare}
                  className="p-3 rounded-full border border-border hover:bg-background-muted transition-all"
                >
                  <Share2 size={20} />
                </button>
              </div>
            </div>

            {/* 3. Description */}
            <p className="text-sm text-foreground-muted leading-relaxed">
              {product.description}
            </p>

            {/* 2. Pricing & Rating */}
            <div className="flex items-center justify-between border-border">
              <div className="flex items-center gap-4">
                <span className="text-3xl font-black">
                  ₹{product.price.toLocaleString()}
                </span>
                {product.discount > 0 && (
                  <span className="text-[10px] font-black bg-destructive text-destructive-foreground px-2 py-1 rounded-sm uppercase italic">
                    {product.discount}% OFF
                  </span>
                )}
              </div>
              <div className="flex items-center gap-1">
                <Star size={14} className="fill-brand text-brand" />
                <span className="text-sm font-black italic">4.5</span>
                <span className="text-[10px] text-foreground-subtle font-bold ml-1 uppercase">
                  (120 Reviews)
                </span>
              </div>
            </div>

            {/* 4. Size Selection */}
            {product.category === "sneakers" && (
              <div className="space-y-4">
                <div className="flex justify-between items-end">
                  <label className="text-[10px] font-black uppercase tracking-widest">
                    Select Size (EU)
                  </label>
                  <Link
                    href="/help/size-guide"
                    className="text-[9px] font-black uppercase underline text-foreground-subtle"
                  >
                    Size Guide
                  </Link>
                </div>
                <div
                  className="grid gap-2"
                  style={{
                    gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))`,
                  }}
                >
                  {sizes.map((size) => (
                    <button
                      key={size}
                      onClick={() => setSelectedSize(size)}
                      className={`py-2 rounded-full border font-black transition-all duration-300 ${
                        selectedSize === size
                          ? "border-brand bg-brand text-brand-foreground scale-95"
                          : "border-border hover:border-foreground-muted"
                      }`}
                    >
                      {size}
                    </button>
                  ))}
                </div>
              </div>
            )}

            <div
              className="w-full py-4 flex justify-center items-center text-xl font-black uppercase
             border border-white rounded-full mb-4
             bg-[linear-gradient(90deg,#ffffff,#9ca3af,#ffffff,#9ca3af,#ffffff)]
             bg-[length:400%_100%]
             bg-clip-text text-transparent
             animate-[glaze_5s_linear_infinite]"
            >
              Buy Now
            </div>

            {/* 5. CTA Buttons */}
            <div className="w-full z-50 bg-black">
              {product.stock > 0 ? (
                <div className="flex items-center gap-1 bg-foreground text-background rounded-full p-1 shadow-2xl">
                  {/* Wishlist */}
                  <button
                    onClick={() => setIsWishlisted((prev) => !prev)}
                    aria-label="Toggle wishlist"
                    className={`h-14 w-14 flex-shrink-0 flex items-center justify-center
    rounded-full border-2 transition-all duration-300 ${
      isWishlisted
        ? "bg-background text-foreground border-foreground scale-95"
        : "border-background text-background hover:bg-background/10"
    }`}
                  >
                    {isWishlisted ? (
                      <Heart size={20} fill="currentColor" />
                    ) : (
                      <HeartPlus size={20} />
                    )}
                  </button>

                  {/* Add to Cart */}
                  <button
                    disabled={!selectedSize}
                    className={`py-4 flex-1 rounded-full font-bold uppercase flex items-center justify-center gap-3 transition-all ${
                      selectedSize
                        ? "bg-background text-foreground hover:scale-[1.02] active:scale-95"
                        : "bg-foreground border-2 border-background text-background cursor-not-allowed"
                    }`}
                  >
                    <ShoppingBag size={16} />
                    Add to Cart
                  </button>
                </div>
              ) : (
                <button className="w-full h-16 border-2 border-destructive text-destructive font-black uppercase tracking-[0.2em] rounded-full flex items-center justify-center gap-3">
                  <Bell size={20} />
                  Notify Me
                </button>
              )}
            </div>

            {/* 6. Trust Cards */}
            <div className="grid grid-cols-2 gap-3 pt-4">
              {[
                {
                  icon: <Truck size={18} />,
                  label: "Fast Delivery",
                  sub: "2-4 Business Days",
                },
                {
                  icon: <RotateCcw size={18} />,
                  label: "7 Day Returns",
                  sub: "Hassle-free policy",
                },
                {
                  icon: <ShieldCheck size={18} />,
                  label: "Authentic Quality",
                  sub: `${product.quality} Grade`,
                },
                {
                  icon: <Star size={18} />,
                  label: "Top Rated",
                  sub: "Trusted by 5k+ users",
                },
              ].map((item, i) => (
                <div
                  key={i}
                  className="p-4 rounded-2xl bg-background-muted border border-border flex items-center gap-3"
                >
                  <div className="text-brand shrink-0">{item.icon}</div>
                  <div>
                    <h4 className="text-[9px] font-black uppercase leading-tight">
                      {item.label}
                    </h4>
                    <p className="text-[8px] text-foreground-subtle font-bold">
                      {item.sub}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* --- REVIEWS HIGHLIGHT --- */}
      <section className="max-w-4xl mx-auto px-6 pb-20">
        <div className="bg-background-muted p-8 md:p-12 rounded-[3rem] border border-border">
          <h3 className="text-xl font-black uppercase italic mb-8">
            Community Verdict
          </h3>
          <div className="space-y-8">
            {product.reviews.map((rev, i) => (
              <div
                key={i}
                className="flex flex-col md:flex-row gap-6 items-start pb-8 border-b border-border last:border-0"
              >
                <img
                  src={rev.userImage}
                  className="w-12 h-12 rounded-full border border-border grayscale hover:grayscale-0 transition-all"
                />
                <div className="flex-1">
                  <div className="flex gap-1 mb-2">
                    {[...Array(5)].map((_, i) => (
                      <Star
                        key={i}
                        size={10}
                        className="fill-brand text-brand"
                      />
                    ))}
                  </div>
                  <p className="text-lg font-bold italic mb-2">
                    "{rev.comment}"
                  </p>
                  <p className="text-[10px] font-black uppercase text-foreground-subtle">
                    {rev.userName} • Verified Buyer
                  </p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>
    </div>
  );
}

